Method.Implementation:
 Set ..Adapter.WebServiceClientClass = "Sh276Ws.SH2767ServiceSoap"
 $$$TRACE("Before calling the service")
 $$$TRACE("claimId: "_pRequest.claimId)
 $$$TRACE("subscriberId: "_pRequest.subscriberId)
    $$$TRACE("memberDOB : "_ pRequest.memberDOB )
    $$$TRACE("memberFirstName : "_ pRequest.memberFirstName )
    $$$TRACE("memberLastName : "_ pRequest.memberLastName )
    $$$TRACE("providerId : "_ pRequest.providerId )
    $$$TRACE("providerIdType : "_ pRequest.providerIdType )
    $$$TRACE("providerFirstName : "_ pRequest.providerFirstName )
    $$$TRACE("providerLastName : "_ pRequest.providerLastName )
    $$$TRACE("csFromDate : "_ pRequest.claimServiceFromDate )
    $$$TRACE("csToDate : "_ pRequest.claimServiceToDate )

    $$$TRACE("totalBilledAmount : "_ pRequest.totalBilledAmount )
    $$$TRACE("subscriberFlag : "_ pRequest.subscriberFlag )
    set cid=pRequest.claimId
    if cid="" {
	  set cid=" "
    }
    set sid=pRequest.subscriberId
    if sid="" {
	  set sid=" "
    }
    set pid=pRequest.providerId
    if pid="" {
	  set pid=" "
    }
    set pidType=pRequest.providerIdType
    if pidType="" {
	  set pidType=" "
    }
    set mDob=pRequest.memberDOB
    if mDob="" {
	  set mDob=" "
    }
    set csFdt=pRequest.claimServiceFromDate
    if csFdt="" {
	    set csFdt=" "
    }
    set csTdt=pRequest.claimServiceToDate
    if csTdt="" {
	    set csTdt=" "
    }
    set amnt=pRequest.totalBilledAmount
    if amnt="" {
	    set amnt=" "
    }
    set mFnm=pRequest.memberFirstName
    if mFnm="" {
	  set mFnm=" "
    }
    set mLnm=pRequest.memberLastName
    if mLnm="" {
	  set mLnm=" "
    }

    set pFnm=pRequest.providerFirstName
    if pFnm="" {
	  set pFnm=" "
    }
    set pLnm=pRequest.providerLastName
    if pLnm="" {
	  set pLnm=" "
    }
    set sFlg=pRequest.subscriberFlag
    if sFlg="" {
	  set sFlg=" "
    }
    set clFlg=pRequest.claimLineFlag
    if clFlg="" {
	  set clFlg=" "
    }

    Set tSC = ..Adapter.InvokeMethod("GetClaimDetails",.GetClaimDetailsResult,cid,pid,sid,csTdt,csFdt,amnt,mLnm,mFnm,mDob,pFnm,pLnm,pidType,sFlg,clFlg," "," "," "," "," "," ")  //Quit:$$$ISERR(tSC) tSC
    $$$TRACE("Called the service")
    if $$$ISERR(tSC) {
	    set errTxt = $System.Status.GetErrorText(%objlasterror)
	    set pResponse = ##class(Response.GetClaimDetailsResponse).%New()
	    set errRec	=##class(Sh276Ws.tns.Outbound277Record).%New()
	    set errRec.ErrorFlag="Y"
	 	set errRec.ErrorMessage=errTxt
	 	set errRec.ClaimFoundFlag="N"

	    Do pResponse.GetClaimDetailsResult.Insert(errRec)
		$$$LOGERROR("SH Service call failed: " _errTxt)
    }
    else {
       Set tSC = pRequest.NewResponse(.pResponse) // Quit:$$$ISERR(tSC) tSC
       Set pResponse.GetClaimDetailsResult=$get(GetClaimDetailsResult)
       $$$TRACE("Response Count: "_pResponse.GetClaimDetailsResult.Count())
       $$$TRACE("Response ClaimFoundFlag: "_pResponse.GetClaimDetailsResult.GetAt(1).ClaimFoundFlag)
       $$$TRACE("Response ErrorMessage: "_pResponse.GetClaimDetailsResult.GetAt(1).ErrorMessage)
       $$$TRACE("Response SubscriberFlag: "_pResponse.GetClaimDetailsResult.GetAt(1).SubscriberFlag)
       $$$TRACE("Response StatusCode011: "_pResponse.GetClaimDetailsResult.GetAt(1).StatusCode011.GetNext())
    }


 Quit $$$OK
